//! Wolfram exact-transform golden replay.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `wolfram/transform_golden.wls` at 50 digits) carries exact DFT/DCT-II/
//! DST-II matrices with Sonium's unnormalized signs, so a forward/inverse
//! round trip cannot hide paired sign/scale bugs: absolute outputs are
//! compared, including the inverse 1/N normalization. A convolution and
//! rectangular-window STFT frames pin the composite paths against the same
//! oracle.

use num_complex::Complex64;
use serde::Deserialize;
use sonium_fft::{
    DctPlan, DstPlan, FftPlanner, LinearConvolutionPlan, StftConfig, StftPlan, WindowFunction,
    dct2, dst2,
};

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");
const TOLERANCE: f64 = 1e-12;

#[derive(Debug, Deserialize)]
struct ComplexScalar {
    re: String,
    im: String,
}

#[derive(Debug, Deserialize)]
struct DftNamedCase {
    name: String,
    case: DftCase,
}

#[derive(Debug, Deserialize)]
struct DftCase {
    n: usize,
    matrix_re: Vec<Vec<String>>,
    matrix_im: Vec<Vec<String>>,
    input: Vec<ComplexScalar>,
    forward: Vec<ComplexScalar>,
    inverse_of_forward: Vec<ComplexScalar>,
}

#[derive(Debug, Deserialize)]
struct RealNamedCase {
    name: String,
    case: RealCase,
}

#[derive(Debug, Deserialize)]
struct RealCase {
    n: usize,
    input: Vec<String>,
    output: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct ConvolutionCase {
    lhs: Vec<String>,
    rhs: Vec<String>,
    output: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct StftCase {
    signal: Vec<String>,
    fft_size: usize,
    hop_size: usize,
    frames: Vec<Vec<ComplexScalar>>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    precision_digits: u32,
    generator: String,
    dft: Vec<DftNamedCase>,
    real: Vec<RealNamedCase>,
    convolution: ConvolutionCase,
    stft_rectangular_8_4: StftCase,
}

fn parse_f64(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_complex(value: &ComplexScalar) -> Complex64 {
    Complex64::new(parse_f64(&value.re), parse_f64(&value.im))
}

fn assert_complex_close(actual: &[Complex64], expected: &[ComplexScalar], label: &str) {
    assert_eq!(actual.len(), expected.len(), "{label}: length mismatch");
    for (index, (got, want)) in actual.iter().zip(expected).enumerate() {
        let want = parse_complex(want);
        let allowed = TOLERANCE * want.norm().max(1.0);
        assert!(
            (got - want).norm() <= allowed,
            "{label}[{index}]: got={got:?}, want={want:?}"
        );
    }
}

fn assert_real_close(actual: &[f64], expected: &[String], label: &str) {
    assert_eq!(actual.len(), expected.len(), "{label}: length mismatch");
    for (index, (&got, want)) in actual.iter().zip(expected).enumerate() {
        let want = parse_f64(want);
        let allowed = TOLERANCE * want.abs().max(1.0);
        assert!(
            (got - want).abs() <= allowed,
            "{label}[{index}]: got={got:e}, want={want:e}"
        );
    }
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Wolfram transform fixture");
    assert_eq!(fixture.schema, "sonium-fft.wolfram-golden.v1");
    assert_eq!(fixture.precision_digits, 50);
    assert!(fixture.generator.contains("Wolfram Engine"));
    fixture
}

#[test]
fn dft_forward_matches_wolfram_matrix() {
    let fixture = parse_fixture();
    assert_eq!(fixture.dft.len(), 3);
    for named in &fixture.dft {
        let case = &named.case;
        let input: Vec<Complex64> = case.input.iter().map(parse_complex).collect();
        let planner = FftPlanner::<f64>::new();
        let plan = planner.plan_forward(case.n);
        let mut actual = input.clone();
        plan.process(&mut actual);
        assert_complex_close(&actual, &case.forward, &format!("{} forward", named.name));
    }
}

#[test]
fn dft_inverse_matches_wolfram_normalization() {
    // Absolute inverse comparison pins the 1/N scale: a paired forward-1/N /
    // inverse-N bug would survive a round trip but fails here.
    let fixture = parse_fixture();
    for named in &fixture.dft {
        let case = &named.case;
        let forward: Vec<Complex64> = case.forward.iter().map(parse_complex).collect();
        let planner = FftPlanner::<f64>::new();
        let plan = planner.plan_inverse(case.n);
        let mut actual = forward;
        plan.process(&mut actual);
        let n = case.n as f64;
        let scaled: Vec<Complex64> = actual.iter().map(|value| value / n).collect();
        assert_complex_close(
            &scaled,
            &case.inverse_of_forward,
            &format!("{} inverse/{}", named.name, case.n),
        );
    }
}

#[test]
fn dft_matrix_is_unitary_up_to_scale() {
    // Oracle self-consistency: M M*/N = I catches generator defects before
    // trusting the matrix entries.
    let fixture = parse_fixture();
    for named in &fixture.dft {
        let case = &named.case;
        let n = case.n;
        let entry = |store: &[Vec<String>], j: usize, k: usize| parse_f64(&store[j][k]);
        for (j, row) in case.matrix_re.iter().enumerate() {
            assert_eq!(row.len(), n, "{} row {j} width", named.name);
        }
        for j in 0..n {
            for l in 0..n {
                let mut real = 0.0;
                let mut imag = 0.0;
                for k in 0..n {
                    let a_re = entry(&case.matrix_re, j, k);
                    let a_im = entry(&case.matrix_im, j, k);
                    let b_re = entry(&case.matrix_re, l, k);
                    let b_im = entry(&case.matrix_im, l, k);
                    real += a_re * b_re + a_im * b_im;
                    imag += a_im * b_re - a_re * b_im;
                }
                let expected = if j == l { n as f64 } else { 0.0 };
                let allowed = 1e-9 * (n as f64).max(1.0);
                assert!(
                    (real - expected).abs() <= allowed && imag.abs() <= allowed,
                    "{} M M*[{j},{l}] = ({real:.6e},{imag:.6e}), want ({expected},0)",
                    named.name,
                );
            }
        }
    }
}

#[test]
fn dct2_and_dst2_match_wolfram_matrices() {
    let fixture = parse_fixture();
    assert_eq!(fixture.real.len(), 2);
    for named in &fixture.real {
        let case = &named.case;
        let input: Vec<f64> = case.input.iter().map(|value| parse_f64(value)).collect();
        let mut output = vec![0.0; case.n];
        if named.name.starts_with("dct2") {
            dct2(&input, &mut output);
            let plan = DctPlan::<f64>::new(case.n);
            let mut planned = vec![0.0; case.n];
            plan.forward(&input, &mut planned);
            assert_real_close(&planned, &case.output, &format!("{} plan", named.name));
        } else {
            dst2(&input, &mut output);
            let plan = DstPlan::<f64>::new(case.n);
            let mut planned = vec![0.0; case.n];
            plan.forward(&input, &mut planned);
            assert_real_close(&planned, &case.output, &format!("{} plan", named.name));
        }
        assert_real_close(&output, &case.output, &named.name);
    }
}

#[test]
fn linear_convolution_matches_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.convolution;
    let lhs: Vec<f64> = case.lhs.iter().map(|value| parse_f64(value)).collect();
    let rhs: Vec<f64> = case.rhs.iter().map(|value| parse_f64(value)).collect();
    let plan = LinearConvolutionPlan::<f64>::new(lhs.len(), rhs.len());
    let lhs_complex: Vec<Complex64> = lhs
        .iter()
        .map(|&value| Complex64::new(value, 0.0))
        .collect();
    let rhs_complex: Vec<Complex64> = rhs
        .iter()
        .map(|&value| Complex64::new(value, 0.0))
        .collect();
    let actual = plan.process(&lhs_complex, &rhs_complex);
    let expected: Vec<f64> = case.output.iter().map(|value| parse_f64(value)).collect();
    assert_real_close(
        &actual.iter().map(|value| value.re).collect::<Vec<_>>(),
        &expected
            .iter()
            .map(|value| value.to_string())
            .collect::<Vec<_>>(),
        "convolution re",
    );
    assert!(
        actual.iter().all(|value| value.im.abs() <= 1e-12),
        "real convolution must have vanishing imaginary part"
    );
}

#[test]
fn stft_rectangular_frames_match_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.stft_rectangular_8_4;
    let signal: Vec<f64> = case.signal.iter().map(|value| parse_f64(value)).collect();
    let plan = StftPlan::<f64>::new(StftConfig::new(
        case.fft_size,
        case.hop_size,
        WindowFunction::Rectangular,
    ));
    let spectra = plan.analyze(&signal);
    // Real-input analysis stores the non-redundant half spectrum
    // (fft_size/2 + 1 bins); the Wolfram frames carry all fft_size bins.
    let half = case.fft_size / 2 + 1;
    assert_eq!(
        spectra.len(),
        case.frames.len() * half,
        "frame-major half-spectrum length"
    );
    for (frame, expected) in spectra.chunks_exact(half).zip(case.frames.iter()) {
        let expected_half: Vec<Complex64> = expected[..half]
            .iter()
            .map(|value| Complex64::new(parse_f64(&value.re), parse_f64(&value.im)))
            .collect();
        assert_eq!(frame.len(), expected_half.len(), "stft frame length");
        for (index, (got, want)) in frame.iter().zip(expected_half.iter()).enumerate() {
            let allowed = TOLERANCE * want.norm().max(1.0);
            assert!(
                (got - want).norm() <= allowed,
                "stft frame bin {index}: got={got:?}, want={want:?}"
            );
        }
    }

    // Overlap-add reconstruction through the inverse plan: the half spectrum
    // is mirrored to a full Hermitian frame manually, so agreement validates
    // the analyzed frames end to end.
    let planner = FftPlanner::<f64>::new();
    let inverse = planner.plan_inverse(case.fft_size);
    let mut ola = vec![0.0; signal.len()];
    let mut weight = vec![0.0; signal.len()];
    for (frame_index, frame) in spectra.chunks_exact(half).enumerate() {
        let mut full = frame.to_vec();
        for bin in (1..case.fft_size / 2).rev() {
            full.push(frame[bin].conj());
        }
        assert_eq!(full.len(), case.fft_size);
        inverse.process(&mut full);
        let start = frame_index * case.hop_size;
        for (offset, value) in full.iter().enumerate() {
            ola[start + offset] += value.re / case.fft_size as f64;
            weight[start + offset] += 1.0;
        }
    }
    for (index, ((got, w), want)) in ola.iter().zip(weight.iter()).zip(signal.iter()).enumerate() {
        assert!(
            (got / w - want).abs() <= 1e-9 * want.abs().max(1.0),
            "ola[{index}]: {got}/{w} != {want}"
        );
    }
}
